// suite: TT-5082
import { describe, expect, test } from "bun:test";

import { bucketOf, weighted } from "./budget-table.ts";

function thrownBy(run: () => unknown): unknown {
	try {
		run();
	} catch (error) {
		return error;
	}
	throw new Error("expected a throw");
}

describe("weighted", () => {
	test("weighs each size by its bucket, on both sides of every bucket edge", () => {
		expect(weighted([0, 349, 350, 1799, 1800, 6999, 7000, 23999, 24000])).toEqual([
			0,
			349 * 0.5,
			350,
			1799,
			1800 * 1.25,
			6999 * 1.25,
			7000 * 1.5,
			23999 * 1.5,
			24000 * 2.25,
		]);
	});

	test("keeps the order of the sizes, not of the buckets", () => {
		expect(weighted([8000, 120, 2400, 400])).toEqual([12000, 60, 3000, 400]);
	});

	test("leaves fractional results unrounded", () => {
		expect(weighted([1, 1801])).toEqual([0.5, 2251.25]);
	});

	test("no sizes gives no weighted sizes", () => {
		expect(weighted([])).toEqual([]);
	});

	test("a negative size throws the same RangeError as bucketOf", () => {
		const fromWeighted = thrownBy(() => weighted([100, -1]));
		const fromBucketOf = thrownBy(() => bucketOf(-1));
		expect(fromWeighted).toBeInstanceOf(RangeError);
		expect((fromWeighted as RangeError).message).toBe((fromBucketOf as RangeError).message);
	});
});

