	test("keeps the first Turn when the list opens with a prompt", () => {
		expect(turnSizes(messages.slice(1))).toEqual(turnSizes(messages));
	});

	test("an empty user prompt still starts a Turn that is counted", () => {
		const emptyPrompt: HarnessMessage = { role: "user", content: "" };
		expect(turnSizes([emptyPrompt, firstReply, secondPrompt, secondReply])).toEqual([
			approximateTokens([emptyPrompt, firstReply]),
			approximateTokens([secondPrompt, secondReply]),
		]);
	});

	test("a list with no user prompt has no Turns", () => {
