		expect(totalOf([])).toBe(0);
	});
});

describe("formatCount", () => {
	test.each([
		[0, "0"],
		[740, "740"],
		[999, "999"],
		[1000, "1.0k"],
		[1234, "1.2k"],
		[1249, "1.2k"],
