import type { HarnessMessage } from "./messages.ts";
import { approximateTokens } from "./tokens.ts";
import { reconstructTurns } from "./turns.ts";

/** Turn-size bucket names, smallest first. */
export const BUCKETS = ["tiny", "small", "medium", "large", "huge"] as const;

/** A Turn-size bucket. */
export type Bucket = (typeof BUCKETS)[number];

/** Exclusive upper bound of each bucket; `huge` has none. */
const BELOW: Record<Bucket, number> = {
	tiny: 350,
	small: 1800,
	medium: 7000,
	large: 24000,
	huge: Infinity,
};

/**
 * The bucket a Turn of `tokens` estimated tokens falls in.
 * @throws RangeError if `tokens` is negative or not finite.
 */
export function bucketOf(tokens: number): Bucket {
	if (!Number.isFinite(tokens) || tokens < 0) {
		throw new RangeError(`Turn size must be a finite, non-negative token count, got ${tokens}`);
	}
	for (const bucket of BUCKETS) if (tokens < BELOW[bucket]) return bucket;
	return "huge";
}

/**
 * The estimated token size of each Turn in `messages`, in order.
 *
 * Leading-Turn rule: `reconstructTurns` groups any messages before the first
 * user prompt (e.g. a system message or a resumed agent reply) into a leading
 * pseudo-Turn with an empty prompt. That group answers no prompt, so it is not
 * a Turn of the Conversation: it is dropped and its tokens are not counted.
 * Every returned size therefore belongs to a Turn that starts with a user
 * message, and an input with no user message yields `[]`.
 */
export function turnSizes(messages: HarnessMessage[]): number[] {
	const turns = reconstructTurns(messages);
	// Keyed on role, not on an empty `prompt`: a user prompt may itself be empty.
	if (turns[0]?.messages[0]?.role !== "user") turns.shift();
	return turns.map((turn) => approximateTokens(turn.messages));
}

/**
 * How many of `sizes` fall in each bucket, largest bucket first. Every bucket
 * gets an entry, even with a count of 0, except `huge`, which is left out
 * when no size falls in it.
 * @throws RangeError if a size is negative or not finite (see `bucketOf`).
 */
export function histogram(sizes: number[]): { bucket: Bucket; count: number }[] {
	const counts: Record<Bucket, number> = { tiny: 0, small: 0, medium: 0, large: 0, huge: 0 };
	for (const size of sizes) counts[bucketOf(size)] += 1;
	return [...BUCKETS]
		.reverse()
		.map((bucket) => ({ bucket, count: counts[bucket] }))
		.filter(({ bucket, count }) => bucket !== "huge" || count > 0);
}

/** The plain sum of `sizes`; 0 for none. */
export function totalOf(sizes: number[]): number {
	let total = 0;
	for (const size of sizes) total += size;
	return total;
}

/** What a Turn's size is multiplied by in each bucket. */
const WEIGHT: Record<Bucket, number> = {
	tiny: 0.5,
	small: 1,
	medium: 1.25,
	large: 1.5,
	huge: 2.25,
};

/**
 * Each size times the weight of its bucket, rounded to the nearest multiple of
 * 10 with halves rounding up, in the order of `sizes`.
 * @throws RangeError if a size is negative or not finite (see `bucketOf`).
 */
export function weighted(sizes: number[]): number[] {
	return sizes.map((size) => Math.round((size * WEIGHT[bucketOf(size)]) / 10) * 10);
}

/**
 * `n` as shown in a rendered table: below 1000 as is (`740`); otherwise in
 * thousands with exactly one decimal and a `k` suffix, halves rounding up
 * (1234 is `1.2k`, 1250 is `1.3k`, 12000 is `12.0k`).
 */
export function formatCount(n: number): string {
	if (n < 1000) return String(n);
	const tenths = Math.round(n / 100);
	return `${Math.floor(tenths / 10)}.${tenths % 10}k`;
}

/** The row label of each bucket in a rendered table. */
const LABEL: Record<Bucket, string> = {
	tiny: "crumbs",
	small: "bites",
	medium: "meals",
	large: "feasts",
	huge: "banquets",
};

/** The row label of `bucket` in a rendered table. */
export function labelOf(bucket: Bucket): string {
	return LABEL[bucket];
}

