import { bucketTotals, formatCount, histogram, labelOf } from "./budget-table.ts";

/** Separates the columns of a rendered row; no padding or alignment. */
const COLUMN = " | ";

/**
 * The table of `sizes` as rows: the header, then one row per `histogram`
 * entry, in its order, as `<label> | <count> | <weighted total>`. The weighted
 * total is the bucket's `bucketTotals` entry, shown through `formatCount`.
 * @throws RangeError if a size is negative or not finite (see `bucketOf`).
 */
export function renderTable(sizes: number[]): string[] {
	const totals = bucketTotals(sizes);
	const rows = histogram(sizes).map(({ bucket, count }) =>
		[labelOf(bucket), String(count), formatCount(totals.get(bucket) ?? 0)].join(COLUMN),
	);
	return [["bucket", "turns", "weighted"].join(COLUMN), ...rows];
}

