export function bucketTotals(sizes: number[]): Map<Bucket, number> {
…
}

/**
 * `n` as shown in a rendered table: below 1000 as is (`740`); otherwise in
 * thousands with exactly one decimal and a `k` suffix, halves rounding up
 * (1234 is `1.2k`, 1250 is `1.3k`, 12000 is `12.0k`).
 */
export function formatCount(n: number): string {
	if (n < 1000) return String(n);
	const tenths = Math.round(n / 100);
	return `${Math.floor(tenths / 10)}.${tenths % 10}k`;
}

/** The row label of each bucket in a rendered table. */
const LABEL: Record<Bucket, string> = {
	tiny: "crumbs",
	small: "bites",
	medium: "meals",
	large: "feasts",
	huge: "banquets",
};

/** The row label of `bucket` in a rendered table. */
export function labelOf(bucket: Bucket): string {
	return LABEL[bucket];
}

/** Turns strictly larger than this many tokens count towards `over=`. */
const OVER = 9000;

/**
 * One line summarising `sizes` against `budget`, fields joined by ` · `:
 * `turns=<n> · total=<n> · used=<p>% · peak=<bucket> · over=<n>`. `total` is
 * unweighted; `used` is the total as a percentage of `budget`, rounded down and
 * possibly above 100; `peak` is the largest bucket holding a Turn, or `none`
 * when there are none; `over` counts Turns larger than 9000 tokens.
 * @throws RangeError if a size is negative or not finite (see `bucketOf`), or
 * if `budget` is not a finite positive number.
 */
export function summaryLine(sizes: number[], budget: number): string {
	if (!Number.isFinite(budget) || budget <= 0) {
		throw new RangeError(`Budget must be a finite, positive token count, got ${budget}`);
	}
	let peak: Bucket | "none" = "none";
	let over = 0;
	for (const size of sizes) {
		const bucket = bucketOf(size);
		if (peak === "none" || BUCKETS.indexOf(bucket) > BUCKETS.indexOf(peak)) peak = bucket;
		if (size > OVER) over += 1;
	}
	const total = totalOf(sizes);
	const used = Math.floor((total * 100) / budget);
	return [`turns=${sizes.length}`, `total=${total}`, `used=${used}%`, `peak=${peak}`, `over=${over}`].join(" · ");
}

