import { describe, expect, test } from "bun:test";

import type { HarnessMessage } from "./messages.ts";
import { renderTable } from "./budget-render.ts";
import {
	bucketOf,
	bucketTotals,
	formatCount,
	histogram,
	labelOf,
	totalOf,
	summaryLine,
	turnSizes,
	type Bucket,
} from "./budget-table.ts";
import { approximateTokens } from "./tokens.ts";

describe("bucketOf", () => {
	const boundaries: [number, Bucket][] = [
		[0, "tiny"],
		[349, "tiny"],
		[350, "small"],
		[1799, "small"],
		[1800, "medium"],
		[6999, "medium"],
		[7000, "large"],
		[23999, "large"],
		[24000, "huge"],
	];

	test.each(boundaries)("%p tokens is %p", (tokens, bucket) => {
		expect(bucketOf(tokens)).toBe(bucket);
	});

	test.each([-1, -0.5, NaN, Infinity, -Infinity])("%p tokens throws RangeError", (tokens) => {
		expect(() => bucketOf(tokens)).toThrow(RangeError);
	});
});

describe("turnSizes", () => {
	const leading: HarnessMessage = { role: "assistant", content: "Resumed from an earlier session.".repeat(5) };
	const firstPrompt: HarnessMessage = { role: "user", content: "Sum the column." };
	const firstReply: HarnessMessage = { role: "assistant", content: "The column sums to 42." };
	const secondPrompt: HarnessMessage = { role: "user", content: "Now the row, please, and show the working.".repeat(3) };
	const secondReply: HarnessMessage = { role: "assistant", content: "The row sums to 7.".repeat(8) };
	const messages = [leading, firstPrompt, firstReply, secondPrompt, secondReply];

	test("sizes each prompt with its reply, in order, and drops the messages before the first prompt", () => {
		expect(turnSizes(messages)).toEqual([
			approximateTokens([firstPrompt, firstReply]),
			approximateTokens([secondPrompt, secondReply]),
		]);
	});

	test("keeps the first Turn when the list opens with a prompt", () => {
		expect(turnSizes(messages.slice(1))).toEqual(turnSizes(messages));
	});

	test("an empty user prompt still starts a Turn that is counted", () => {
		const emptyPrompt: HarnessMessage = { role: "user", content: "" };
		expect(turnSizes([emptyPrompt, firstReply, secondPrompt, secondReply])).toEqual([
			approximateTokens([emptyPrompt, firstReply]),
			approximateTokens([secondPrompt, secondReply]),
		]);
	});

	test("a list with no user prompt has no Turns", () => {
		expect(turnSizes([leading])).toEqual([]);
		expect(turnSizes([])).toEqual([]);
	});
});

describe("histogram", () => {
	test("the samples.md example: largest first, huge left out", () => {
		expect(histogram([120, 90, 2400, 400, 8000])).toEqual([
			{ bucket: "large", count: 1 },
			{ bucket: "medium", count: 1 },
			{ bucket: "small", count: 1 },
			{ bucket: "tiny", count: 2 },
		]);
	});

	test("with no huge size, huge is left out but other empty buckets stay at 0", () => {
		expect(histogram([23999, 349, 0])).toEqual([
			{ bucket: "large", count: 1 },
			{ bucket: "medium", count: 0 },
			{ bucket: "small", count: 0 },
			{ bucket: "tiny", count: 2 },
		]);
	});

	test("huge leads when a size falls in it, and other empty buckets stay at 0", () => {
		expect(histogram([24000, 30000, 100])).toEqual([
			{ bucket: "huge", count: 2 },
			{ bucket: "large", count: 0 },
			{ bucket: "medium", count: 0 },
			{ bucket: "small", count: 0 },
			{ bucket: "tiny", count: 1 },
		]);
	});

	test("no sizes gives every bucket but huge at 0", () => {
		expect(histogram([])).toEqual([
			{ bucket: "large", count: 0 },
			{ bucket: "medium", count: 0 },
			{ bucket: "small", count: 0 },
			{ bucket: "tiny", count: 0 },
		]);
	});

	test("an invalid size throws RangeError", () => {
		expect(() => histogram([100, -1])).toThrow(RangeError);
	});
});

describe("totalOf", () => {
	test("sums the sizes, and is 0 for none", () => {
		expect(totalOf([120, 90, 2400, 400, 8000])).toBe(11010);
		expect(totalOf([])).toBe(0);
	});
});

describe("bucketTotals", () => {
	test("sums each bucket's weighted sizes, every bucket present smallest first", () => {
		// Weighted: 120 → 60, 90 → 45 → 50, 2400 → 3000, 400 → 400, 8000 → 12000.
		expect([...bucketTotals([120, 90, 2400, 400, 8000])]).toEqual([
			["tiny", 110],
			["small", 400],
			["medium", 3000],
			["large", 12000],
			["huge", 0],
		]);
	});

	test("rounds each Turn before summing, not the bucket's sum", () => {
		// Each 10 weighs 5, which rounds up to 10; the unrounded sum 10 would stay 10.
		expect(bucketTotals([10, 10]).get("tiny")).toBe(20);
	});

	test("no sizes gives every bucket at 0", () => {
		expect([...bucketTotals([])]).toEqual([
			["tiny", 0],
			["small", 0],
			["medium", 0],
			["large", 0],
			["huge", 0],
		]);
	});

	test("an invalid size throws RangeError", () => {
		expect(() => bucketTotals([100, -1])).toThrow(RangeError);
	});
});

describe("formatCount", () => {
	test.each([
		[0, "0"],
		[740, "740"],
		[999, "999"],
		[1000, "1.0k"],
		[1234, "1.2k"],
		[1249, "1.2k"],
		[1250, "1.3k"],
		[9950, "10.0k"],
		[12000, "12.0k"],
		[123456, "123.5k"],
	])("%p is shown as %p", (n, shown) => {
		expect(formatCount(n)).toBe(shown);
	});
});

describe("labelOf", () => {
	const labels: [Bucket, string][] = [
		["tiny", "crumbs"],
		["small", "bites"],
		["medium", "meals"],
		["large", "feasts"],
		["huge", "banquets"],
	];

