describe("renderTable", () => {
	test("a header, then a row per histogram entry, largest bucket first, totals through formatCount", () => {
		expect(renderTable([120, 90, 2400, 400, 8000])).toEqual([
			"bucket | turns | weighted",
			"feasts | 1 | 12.0k",
			"meals | 1 | 3.0k",
			"bites | 1 | 400",
			"crumbs | 2 | 110",
		]);
	});

	test("a banquets row appears only when a size is huge", () => {
		expect(renderTable([24000, 30000, 100])).toEqual([
			"bucket | turns | weighted",
			"banquets | 2 | 121.5k",
			"feasts | 0 | 0",
			"meals | 0 | 0",
			"bites | 0 | 0",
			"crumbs | 1 | 50",
		]);
	});

	test("no sizes still renders the header and the empty rows", () => {
		expect(renderTable([])).toEqual([
			"bucket | turns | weighted",
			"feasts | 0 | 0",
			"meals | 0 | 0",
			"bites | 0 | 0",
			"crumbs | 0 | 0",
		]);
	});

	test("an invalid size throws RangeError", () => {
		expect(() => renderTable([100, -1])).toThrow(RangeError);
	});
});

describe("summaryLine", () => {
	test("turns, unweighted total, floored percentage, then the footer fields", () => {
		expect(summaryLine([7000, 2000, 400], 20000)).toBe("turns=3 · total=9400 · used=47% · peak=large · over=0");
	});

	test("used rounds down and may exceed 100", () => {
		expect(summaryLine([1999], 1000)).toBe("turns=1 · total=1999 · used=199% · peak=medium · over=0");
	});

	test("over counts only Turns strictly larger than 9000; peak is the largest bucket", () => {
		expect(summaryLine([9000, 9001, 30000, 10], 100000)).toBe(
			"turns=4 · total=48011 · used=48% · peak=huge · over=2",
		);
	});

	test("no sizes gives peak=none", () => {
		expect(summaryLine([], 5000)).toBe("turns=0 · total=0 · used=0% · peak=none · over=0");
	});

	test("no sizes still throws RangeError for an invalid budget", () => {
		expect(() => summaryLine([], 0)).toThrow(RangeError);
	});

	test("an invalid size throws RangeError", () => {
		expect(() => summaryLine([100, -1], 5000)).toThrow(RangeError);
	});

	test.each([0, -1, NaN, Infinity])("a budget of %p throws RangeError", (budget) => {
		expect(() => summaryLine([100], budget)).toThrow(RangeError);
	});
